import { Component, Element, h, Host, Prop, Watch } from '@stencil/core';
import { BadgeDisplayMode, BadgeMainColor, BadgePosition } from '../../types';

/**
 * @slot parent - parent which the badge refers to
 * @slot content - content of the badge
 */
@Component({
  tag: 'groupui-badge',
  styleUrl: 'badge.scss',
  shadow: true,
})
export class Badge {
  /**
   * the position of the badge.
   */
  @Prop({ reflect: true }) readonly position: BadgePosition = 'top-right';

  /**
   * the color of the badge.
   */
  @Prop({ reflect: true }) readonly color: BadgeMainColor = 'information';

  /**
   * the color of the border.
   */
  @Prop({ reflect: true }) readonly borderColor: string = 'transparent';

  /**
   * offset of the badge in the x direction.
   */
  @Prop({ reflect: true }) readonly offsetX: string = '0px';

  /**
   * offset of the badge in the y direction.
   */
  @Prop({ reflect: true }) readonly offsetY: string = '0px';

  /**
   * sets parent display mode
   */
  @Prop({ reflect: true }) readonly display: BadgeDisplayMode = 'inline';

  @Element() host: HTMLElement;

  componentDidLoad() {
    this.onOutlineColorChanged();
    this.onOffsetXChanged();
    this.onOffsetYChanged();
  }

  private isContentSlotProvided(): boolean {
    return !!this.host.querySelector('[slot="content"]');
  }

  @Watch('offsetX')
  onOffsetXChanged() {
    this.host.style.setProperty('--offset-x', this.sanitizeZeroValue(this.offsetX));
  }

  @Watch('offsetY')
  onOffsetYChanged() {
    this.host.style.setProperty('--offset-y', this.sanitizeZeroValue(this.offsetY));
  }

  private sanitizeZeroValue(value: string) {
    return value === '0' ? '0px' : value;
  }

  @Watch('borderColor')
  onOutlineColorChanged() {
    this.host.style.setProperty('--border-color', this.borderColor);
  }

  render() {
    return (
      <Host>
        <slot name="parent" />
        <div class="badge-container">
          {this.isContentSlotProvided() ? (
            <div class="badge text-badge">
              <slot name="content" />
            </div>
          ) : (
            <div class="badge indicator-badge"></div>
          )}
        </div>
      </Host>
    );
  }
}
